import { computed } from "vue";
import { menuConnect, menuMachine } from "@/lib/utils";
import { normalizeProps, useMachine } from "@zag-js/vue";
import type { PositioningOptions } from "@zag-js/popper";

export function useDropdownMenu(props: {
    id?: string;
    open?: boolean;
    defaultOpen?: boolean;
    closeOnSelect?: boolean;
    loopFocus?: boolean;
    positioning?: PositioningOptions;
}, emit: (event: "update:open" | "change", value: boolean) => void) {
    const machineProps = computed(() => ({
        id: props.id,
        open: props.open,
        defaultOpen: props.open === undefined ? props.defaultOpen : undefined,
        closeOnSelect: props.closeOnSelect,
        loopFocus: props.loopFocus,
        positioning: props.positioning,
        onOpenChange(details: { open: boolean }) {
            emit("update:open", details.open);
            emit("change", details.open);
        },
    }));

    const service = useMachine(menuMachine, machineProps);
    const api = computed(() => menuConnect(service, normalizeProps));

    return api;
}

// @ts-nocheck
import { setupDropdownMenuMachine, connectDropdownMenuMachine, type WeappDropdownMenuApi, type WeappDropdownMenuService } from './use-dropdown-menu'

type MenuItemTapEvent = WechatMiniprogram.BaseEvent & {
  currentTarget: {
    dataset: {
      value?: string
    }
  }
}

type WeappDropdownMenuInternal = WechatMiniprogram.Component.InstanceMethods<{}> & {
  _service?: WeappDropdownMenuService
  _cleanup?: () => void
  _send?: (event: object) => void
  data: {
    api: WeappDropdownMenuApi
  }
  properties: {
    open: boolean
    closeOnSelect: boolean
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    open: { type: Boolean, value: false },
    closeOnSelect: { type: Boolean, value: true },
    id: { type: String, value: 'dropdown-menu' },
    extClass: { type: String, value: '' },
  },

  data: {
    api: {} as WeappDropdownMenuApi,
    className: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappDropdownMenuInternal
      const { service, cleanup, send } = setupDropdownMenuMachine(this, {
        id: this.properties.id,
        open: this.properties.open,
        closeOnSelect: this.properties.closeOnSelect,
        onOpenChange: (details) => {
          this.triggerEvent('change', details)
        },
        onSelect: (details) => {
          this.triggerEvent('select', details)
        },
      })

      self._service = service
      self._cleanup = cleanup
      self._send = send
    },
    detached() {
      const self = this as WeappDropdownMenuInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappDropdownMenuInternal
      if (!state || !self._send) return
      const api = connectDropdownMenuMachine(state, self._send)
      this.setData({ api, className: this.properties.extClass })
    },
  },

  methods: {
    onTriggerTap() {
      const self = this as WeappDropdownMenuInternal
      self.data.api.triggerProps?.onClick?.()
    },
    onItemTap(e: MenuItemTapEvent) {
      const self = this as WeappDropdownMenuInternal
      const value = e.currentTarget.dataset.value
      if (value && self.data.api.selectItem) {
        self.data.api.selectItem({ value })
      }
    },
    onBackdropTap() {
      const self = this as WeappDropdownMenuInternal
      self.data.api.setOpen?.(false)
    },
  },
})

