type SwitchPropDefinition = {
  type:
    | StringConstructor
    | BooleanConstructor
    | NumberConstructor
    | ArrayConstructor
    | ObjectConstructor
    | FunctionConstructor
    | null
  value?: string | boolean | number | number[]
}

