                  <Checkbox
                    id={`table-checkbox-${item.id}`}
                    checked={!!selectedRows[item.id]}
                    onCheckedChange={(value) => {
                      const checked = toChecked(value)
                      setSelectedRows((prev) => ({ ...prev, [item.id]: checked }))
                    }}
                    onClick={() => {
                      setSelectedRows((prev) => ({ ...prev, [item.id]: !prev[item.id] }))
                    }}
