Component({
  properties: {
    open: {
      type: Boolean,
      value: false,
    },
    side: {
      type: String,
      value: 'right',
    },
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    contentClass: '',
    overlayClass: '',
  },
  observers: {
    'extClass, side': function (extClass, side) {
      // Mapping side properly to cva
      // Note: we pass `state: open` if variants depend on it?
      // Shared variants use `data-[state=open]`.
      // We render `data-state="open"` in WXML.

      const contentClass = resolveClasses(sheetContentVariants({ side: side as any }), extClass)
      const overlayClass = resolveClasses(sheetOverlayVariants())

      this.setData({
        contentClass,
        overlayClass,
      })
    },
  },
  methods: {
    close() {
      this.triggerEvent('close')
    },
    noop() {},
  },
})

{
  "component": true
}

import { sheetDescriptionVariants } from "@/lib/utils"

import { resolveClasses } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  properties: {
    extClass: { type: String, value: '' },
  },
  data: { baseClass: '' },
  observers: {
    extClass: function (extClass) {
      const { baseClass } = resolveClasses(sheetDescriptionVariants(), extClass)
      this.setData({ baseClass })
    },
  },
})

